begin;
create function pg_temp.check_true(value boolean,message text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Assertion failed: %',message; end if; end $$;
create function pg_temp.expect_error(query text,code text) returns void language plpgsql as $$ begin begin execute query; exception when others then if sqlstate=code then return; else raise; end if; end; raise exception 'Expected error %',code; end $$;
insert into auth.users(id,email_confirmed_at) values('75000000-0000-4000-8000-000000000001',now()),('75000000-0000-4000-8000-000000000002',now()),('75000000-0000-4000-8000-000000000003',now());
insert into public.staff_roles(user_id,role) values('75000000-0000-4000-8000-000000000003','admin');
insert into public.talent_profiles(id,data) values('portfolio-test','{"id":"portfolio-test","name":"Synthetic portfolio","linkedinUrl":"https://www.linkedin.com/in/portfolio-test","claimed":true,"skills":["Embedded"],"checkedAt":"2026-10-13"}');
insert into private.talent_owners(profile_id,user_id) values('portfolio-test','75000000-0000-4000-8000-000000000001');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":null}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":[{}]}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":[{"title":"X","summary":"Y","contribution":"Z","skills":[],"evidenceUrl":"javascript:alert(1)"}]}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":[{"title":"X","summary":"Y","contribution":"Z","skills":[],"evidenceUrl":"https://user:secret@example.org"}]}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":[{"title":"X","summary":"Y","contribution":"Z","skills":[],"evidenceUrl":"","verified":true}]}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":[{"title":"X","summary":"Y","contribution":" ","skills":[],"evidenceUrl":""}]}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"portfolioProjects":[{"title":"X","summary":"Y","contribution":"Z","skills":[123],"evidenceUrl":""}]}')$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch(jsonb_build_object('portfolioProjects',(select jsonb_agg(jsonb_build_object('title','X','summary','Y','contribution','Z','skills','[]'::jsonb,'evidenceUrl','')) from generate_series(1,11))))$q$,'22023');
select pg_temp.expect_error($q$select private.talent_validate_patch('{"claimed":true,"portfolioProjects":[]}')$q$,'22023');
set local role authenticated;
select set_config('request.jwt.claim.sub','75000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error($q$select public.talent_update_profile('portfolio-test',1,'{"portfolioProjects":[]}')$q$,'42501');
select set_config('request.jwt.claim.sub','75000000-0000-4000-8000-000000000001',true);
select pg_temp.check_true((public.talent_update_profile('portfolio-test',1,'{"portfolioProjects":[{"title":"Sensor board","summary":"An open sensor board","contribution":"I implemented the SPI driver","skills":["C++","SPI"],"evidenceUrl":"https://example.org/board"}],"availability":"available"}')->>'revision')::int=2,'owner saves project and availability');
select pg_temp.check_true((select data->'portfolioProjects'->0->>'contribution'='I implemented the SPI driver' and data->>'availability'='available' and data->'skills'='["Embedded"]'::jsonb and data->>'checkedAt'='2026-10-13' from public.talent_profiles where id='portfolio-test'),'contribution saved without replacing research evidence');
select pg_temp.expect_error($q$select public.talent_update_profile('portfolio-test',1,'{"portfolioProjects":[]}')$q$,'P0409');
select set_config('request.jwt.claim.sub','75000000-0000-4000-8000-000000000003',true);
select pg_temp.check_true((public.talent_admin_update_profile('portfolio-test',2,'{"portfolioProjects":[]}','Removed incorrect synthetic project')->>'revision')::int=3,'admin edits project through audited RPC');
reset role;
select pg_temp.check_true((select before_data->'portfolioProjects'->0->>'title'='Sensor board' and after_data->'portfolioProjects'='[]'::jsonb from private.talent_profile_edits where profile_id='portfolio-test'),'admin audit preserves previous project evidence');
rollback;
